Json::Value Reports::toMasqueradedJson(
    const std::vector<std::string> &pMasqueradingVector) const
{
    Json::Value ret;
    if(pMasqueradingVector.size() == 6)
    {
        if(!pMasqueradingVector[0].empty())
        {
            if(getReportId())
            {
                ret[pMasqueradingVector[0]]=getValueOfReportId();
            }
            else
            {
                ret[pMasqueradingVector[0]]=Json::Value();
            }
        }
        if(!pMasqueradingVector[1].empty())
        {
            if(getReporterAccountId())
            {
                ret[pMasqueradingVector[1]]=getValueOfReporterAccountId();
            }
            else
            {
                ret[pMasqueradingVector[1]]=Json::Value();
            }
        }
        if(!pMasqueradingVector[2].empty())
        {
            if(getPriceEntryId())
            {
                ret[pMasqueradingVector[2]]=getValueOfPriceEntryId();
            }
            else
            {
                ret[pMasqueradingVector[2]]=Json::Value();
            }
        }
        if(!pMasqueradingVector[3].empty())
        {
            if(getReasonForReport())
            {
                ret[pMasqueradingVector[3]]=getValueOfReasonForReport();
            }
            else
            {
                ret[pMasqueradingVector[3]]=Json::Value();
            }
        }
        if(!pMasqueradingVector[4].empty())
        {
            if(getReportTimestamp())
            {
                ret[pMasqueradingVector[4]]=getReportTimestamp()->toDbStringLocal();
            }
            else
            {
                ret[pMasqueradingVector[4]]=Json::Value();
            }
        }
        if(!pMasqueradingVector[5].empty())
        {
            if(getResolutionStatus())
            {
                ret[pMasqueradingVector[5]]=getValueOfResolutionStatus();
            }
            else
            {
                ret[pMasqueradingVector[5]]=Json::Value();
            }
        }
        return ret;
    }
    LOG_ERROR << "Masquerade failed";
    if(getReportId())
    {
        ret["report_id"]=getValueOfReportId();
    }
    else
    {
        ret["report_id"]=Json::Value();
    }
    if(getReporterAccountId())
    {
        ret["reporter_account_id"]=getValueOfReporterAccountId();
    }
    else
    {
        ret["reporter_account_id"]=Json::Value();
    }
    if(getPriceEntryId())
    {
        ret["price_entry_id"]=getValueOfPriceEntryId();
    }
    else
    {
        ret["price_entry_id"]=Json::Value();
    }
    if(getReasonForReport())
    {
        ret["reason_for_report"]=getValueOfReasonForReport();
    }
    else
    {
        ret["reason_for_report"]=Json::Value();
    }
    if(getReportTimestamp())
    {
        ret["report_timestamp"]=getReportTimestamp()->toDbStringLocal();
    }
    else
    {
        ret["report_timestamp"]=Json::Value();
    }
    if(getResolutionStatus())
    {
        ret["resolution_status"]=getValueOfResolutionStatus();
    }
    else
    {
        ret["resolution_status"]=Json::Value();
    }
    return ret;
}

bool Reports::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("report_id"))
    {
        if(!validJsonOfField(0, "report_id", pJson["report_id"], err, true))
            return false;
    }
    if(pJson.isMember("reporter_account_id"))
    {
        if(!validJsonOfField(1, "reporter_account_id", pJson["reporter_account_id"], err, true))
            return false;
    }
    if(pJson.isMember("price_entry_id"))
    {
        if(!validJsonOfField(2, "price_entry_id", pJson["price_entry_id"], err, true))
            return false;
    }
    if(pJson.isMember("reason_for_report"))
    {
        if(!validJsonOfField(3, "reason_for_report", pJson["reason_for_report"], err, true))
            return false;
    }
    if(pJson.isMember("report_timestamp"))
    {
        if(!validJsonOfField(4, "report_timestamp", pJson["report_timestamp"], err, true))
            return false;
    }
    if(pJson.isMember("resolution_status"))
    {
        if(!validJsonOfField(5, "resolution_status", pJson["resolution_status"], err, true))
            return false;
    }
    return true;
}
bool Reports::validateMasqueradedJsonForCreation(const Json::Value &pJson,
                                                 const std::vector<std::string> &pMasqueradingVector,
                                                 std::string &err)
{
    if(pMasqueradingVector.size() != 6)
    {
        err = "Bad masquerading vector";
        return false;
    }
    try {
      if(!pMasqueradingVector[0].empty())
      {
          if(pJson.isMember(pMasqueradingVector[0]))
          {
              if(!validJsonOfField(0, pMasqueradingVector[0], pJson[pMasqueradingVector[0]], err, true))
                  return false;
          }
      }
      if(!pMasqueradingVector[1].empty())
      {
          if(pJson.isMember(pMasqueradingVector[1]))
          {
              if(!validJsonOfField(1, pMasqueradingVector[1], pJson[pMasqueradingVector[1]], err, true))
                  return false;
          }
      }
      if(!pMasqueradingVector[2].empty())
      {
          if(pJson.isMember(pMasqueradingVector[2]))
          {
              if(!validJsonOfField(2, pMasqueradingVector[2], pJson[pMasqueradingVector[2]], err, true))
                  return false;
          }
      }
      if(!pMasqueradingVector[3].empty())
      {
          if(pJson.isMember(pMasqueradingVector[3]))
          {
              if(!validJsonOfField(3, pMasqueradingVector[3], pJson[pMasqueradingVector[3]], err, true))
                  return false;
          }
      }
      if(!pMasqueradingVector[4].empty())
      {
          if(pJson.isMember(pMasqueradingVector[4]))
          {
              if(!validJsonOfField(4, pMasqueradingVector[4], pJson[pMasqueradingVector[4]], err, true))
                  return false;
          }
      }
      if(!pMasqueradingVector[5].empty())
      {
          if(pJson.isMember(pMasqueradingVector[5]))
          {
              if(!validJsonOfField(5, pMasqueradingVector[5], pJson[pMasqueradingVector[5]], err, true))
                  return false;
          }
      }
    }
    catch(const Json::LogicError &e)
    {
      err = e.what();
      return false;
    }
    return true;
}
