bool Reports::validJsonOfField(size_t index,
                               const std::string &fieldName,
                               const Json::Value &pJson,
                               std::string &err,
                               bool isForCreation)
{
    switch(index)
    {
        case 0:
            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }
            if(isForCreation)
            {
                err="The automatic primary key cannot be set";
                return false;
            }
            if(!pJson.isInt())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }
            break;
        case 1:
            if(pJson.isNull())
            {
                return true;
            }
            if(!pJson.isInt())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }
            break;
        case 2:
            if(pJson.isNull())
            {
                return true;
            }
            if(!pJson.isInt())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }
            break;
        case 3:
            if(pJson.isNull())
            {
                return true;
            }
            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }
            break;
        case 4:
            if(pJson.isNull())
            {
                return true;
            }
            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }
            break;
        case 5:
            if(pJson.isNull())
            {
                return true;
            }
            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }
            if(pJson.isString() && std::wstring_convert<std::codecvt_utf8_utf16<wchar_t>, wchar_t>{}
                .from_bytes(pJson.asCString()).size() > 50)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 50)";
                return false;
            }
            break;
        default:
            err="Internal error in the server";
            return false;
    }
    return true;
}
std::vector<std::pair<Admins,AdminReports>> Reports::getAdmins(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from admins,admin_reports where admin_reports.report_id = $1 and admin_reports.admin_account_id = admins.account_id";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *reportId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    std::vector<std::pair<Admins,AdminReports>> ret;
    ret.reserve(r.size());
    for (auto const &row : r)
    {
        ret.emplace_back(std::pair<Admins,AdminReports>(
            Admins(row),AdminReports(row,Admins::getColumnNumber())));
    }
    return ret;
}

void Reports::getAdmins(const DbClientPtr &clientPtr,
                        const std::function<void(std::vector<std::pair<Admins,AdminReports>>)> &rcb,
                        const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from admins,admin_reports where admin_reports.report_id = $1 and admin_reports.admin_account_id = admins.account_id";
    *clientPtr << sql
               << *reportId_
               >> [rcb = std::move(rcb)](const Result &r){
                   std::vector<std::pair<Admins,AdminReports>> ret;
                   ret.reserve(r.size());
                   for (auto const &row : r)
                   {
                       ret.emplace_back(std::pair<Admins,AdminReports>(
                           Admins(row),AdminReports(row,Admins::getColumnNumber())));
                   }
                   rcb(ret);
               }
               >> ecb;
}
